void Solver::rephase() {
    rephases = 0;
    threshold *= 0.9;
    rephase_limit += 8192;

    // Adjust phases based on conflict analysis and local best
    int phase_choice = rand() % 100;

    if (phase_choice < 60) {
        // 60%: Use local best phase (most successful assignment)
        for (int i = 1; i <= vars; i++) {
            saved[i] = local_best[i];
        }
    } else if (phase_choice < 80) {
        // 20%: Invert local best phase (explore opposite assignments)
        for (int i = 1; i <= vars; i++) {
            saved[i] = -local_best[i];
        }
    } else if (phase_choice < 90) {
        // 10%: Use current trail phase (continue current direction)
        for (int i = 1; i <= vars; i++) {
            saved[i] = value[i];
            if (saved[i] == 0) {
                // For unassigned variables, keep original saved value
                saved[i] = saved[i] > 0 ? 1 : -1;
            }
        }
    } else {
        // 10%: Random phase (diversification)
        for (int i = 1; i <= vars; i++) {
            saved[i] = rand() % 2 ? 1 : -1;
        }
    }
}
